import { Component, Show } from "solid-js";

import { Icon } from "#core/ui-next/components/icon.jsx";
import { L10n } from "#core/ui-next/components/l10n.jsx";
import { TooltipKeyword } from "#core/ui-next/components/tooltip-keyword.jsx";
import { Tooltip } from "#core/ui-next/components/tooltip.jsx";

import { TicketRow, TicketSection } from "#base/ui-next/tooltips/plot-tooltip/components/utility.jsx";
import { VolcanoFeatureInfo } from "#base/ui-next/tooltips/plot-tooltip/helpers.js";

export interface VolcanoSectionProps {
	volcano: VolcanoFeatureInfo;
}

export const VolcanoSection: Component<VolcanoSectionProps> = (props) => {
	return (
		<TicketSection name="VolcanoSection">
			<TicketRow
				icon={
					<Icon
						class="size-8"
						name={props.volcano.active ? "url(blp:ntf_volcano_active)" : "url(blp:ntf_volcano_inactive)"}
						isUrl
					/>
				}
			>
				<Show
					when={props.volcano.active}
					fallback={
						<L10n.Stylize
							class="font-title text-sm uppercase text-secondary"
							text={"LOC_FEATURE_VOLCANO_NAME_INACTIVE"}
						/>
					}
				>
					<Tooltip.Text
						text="LOC_NOTIFICATION_VOLCANO_ACTIVE_SUMMARY"
						args={[props.volcano.name]}
					>
						<TooltipKeyword>
							<L10n.Stylize
								class="font-title text-sm uppercase"
								text={"LOC_FEATURE_VOLCANO_NAME_ACTIVE"}
							/>
						</TooltipKeyword>
					</Tooltip.Text>
				</Show>

				<L10n.Stylize
					class="font-body text-sm"
					text={props.volcano.name}
				/>
			</TicketRow>
		</TicketSection>
	);
};
